"""Whole-row floor pre-image test over the re-scored untouched failures (review D2, N-01/N-02). Read-only.
Identical test to scratchpad/hp-whr/whr_preimage.py (restore last_reported_ts to NULL on any subset of up to six of
the segment's state rows that carry a non-null value; a match with the FIRST anchored whole-row root shows that the
only change since sealing is last_reported_ts), applied to the untouched failures under the new counting rule of
floor_rescore.py (exp/out/<TAG>_floor_rescore.json). Also reports the bound for a stable-columns scheme (every
column except last_reported_ts): a reproduced segment would pass it; a late-row segment would fail it; the rest
cannot be decided from the final snapshot, because the anchored roots fold in last_reported_ts values that were
overwritten after sealing. Writes exp/out/<TAG>_floor_preimage_d2.json. Usage: d2_preimage.py TAG SNAPSHOT CHAIN"""
import hashlib, itertools, json, os, sys
TAG, DB, CHAIN = sys.argv[1:4]
OUT = "/Users/huanbui/Research/HOMEPROV-P13/exp/out"
dst = os.path.join(OUT, f"{TAG}_floor_preimage_d2.json")
if os.path.exists(dst):
    raise SystemExit("refusing to overwrite " + dst)
os.environ["HOMEPROV_SCRATCH"] = os.path.dirname(DB)
sys.path.insert(0, "/Users/huanbui/Research/HOMEPROV-P13/monitor")
import monitor_wholerow as WR
M = WR.M
rs = json.load(open(os.path.join(OUT, f"{TAG}_floor_rescore.json")))
fails = rs["new_rule_floor"]["second"]["failing"]
first = {}
for line in open(CHAIN):
    if line.strip():
        p = json.loads(line).get("payload") or {}
        for s, v in ((p.get("sealed") or {}).get("second") or {}).items():
            first.setdefault(s, v)
since = (int(rs["window"]["t_start"] // 3600) - 1) * 3600.0
by_seg = {}
for n in WR.load(DB, since=since):
    by_seg.setdefault(str(int(n[0] // 1)), []).append(n)


def root(ns):
    acc = M.ZERO
    for n in ns:
        acc = M.H(acc + WR.node_hash_wholerow(n))
    return acc.hex()


def nulled(n):
    row = json.loads(n[9]); row["row"]["last_reported_ts"] = None
    return n[:9] + (M._canon(row),)


res = {"untouched_failing": len(fails), "explained_by_last_reported_null": 0, "late_rows": 0, "vanished": 0,
       "not_reconstructed": []}
for f in fails:
    s = f["segment"]
    if f["mechanism"] == "rows_arrived_after_seal":
        res["late_rows"] += 1; continue
    if f["mechanism"] == "segment_vanished":
        res["vanished"] += 1; continue
    ns = by_seg.get(s, []); v = first[s]
    cand = [i for i, n in enumerate(ns) if n[1].startswith("s:") and json.loads(n[9])["row"].get("last_reported_ts") is not None]
    hit = False
    for k in range(1, min(len(cand), 6) + 1):
        for sub in itertools.combinations(cand, k):
            if root([nulled(n) if i in sub else n for i, n in enumerate(ns)]) == v["acc"]:
                hit = True; break
        if hit:
            break
    if hit:
        res["explained_by_last_reported_null"] += 1
    else:
        res["not_reconstructed"].append({"segment": s, "rows": len(ns), "state_rows_with_last_reported": len(cand)})
n_untouched = rs["new_rule_floor"]["second"]["n"]
res["stable_columns_bound"] = {"untouched_segments": n_untouched, "certain_failures": res["late_rows"] + res["vanished"],
                               "at_most_failures": res["late_rows"] + res["vanished"] + len(res["not_reconstructed"])}
src = open(__file__).read()
res.update({"tag": TAG, "how": __doc__, "script_sha256": hashlib.sha256(src.encode()).hexdigest(), "script": src,
            "rescore_file_sha256": hashlib.sha256(open(os.path.join(OUT, f"{TAG}_floor_rescore.json"), "rb").read()).hexdigest()})
json.dump(res, open(dst, "w"), indent=1)
print(TAG, {k: (v if k != "not_reconstructed" else len(v)) for k, v in res.items() if k not in ("how", "script")})
